import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CleanQuoteAnimationProps = Record<string, any>;

const CleanQuoteAnimation: React.FC<CleanQuoteAnimationProps> = ({
  backgroundColor = "#ffffff",
  titleColor = "#1a1a1a",
  transparentBackground = false,
  titleText = "Edit for attention, not aesthetics.",
  fontSize = 70,
  fontWeight = 700,
  staggerFrame = 5,
  durationInSeconds = 5,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter", "Playfair Display"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const words = titleText.split(" ");

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          flexWrap: "wrap",
          justifyContent: "center",
          alignItems: "center",
          maxWidth: "80%",
          gap: fontSize * 0.3,
        }}
      >
        {words.map((word, i) => {
          const delay = i * staggerFrame;
          
          const progress = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 15,
              stiffness: 120,
              mass: 0.8,
            },
          });

          const opacity = progress;
          const translateY = (1 - progress) * 20;
          const scale = 0.9 + (progress * 0.1);

          // Check if word is "not" or "aesthetics" (ignoring punctuation for match)
          const cleanWord = word.replace(/[^a-zA-Z0-9]/g, "").toLowerCase();
          const isSpecial = cleanWord === "not" || cleanWord === "aesthetics";
          
          const currentFontFamily = isSpecial ? '"Playfair Display", serif' : "inherit";

          return (
            <span
              key={i}
              style={{
                opacity,
                transform: `translateY(${translateY}px) scale(${scale})`,
                color: titleColor,
                fontSize,
                fontWeight,
                fontFamily: currentFontFamily,
                display: "inline-block",
                transition: "none", // Mandatory
              }}
            >
              {word}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default CleanQuoteAnimation;